        else:
            cmd = "top -bn1 | grep 'Cpu(s)' | awk '{print $2 + $4}'"
            cpu_usage = subprocess.check_output(cmd, shell=True).decode().strip()

        logs.append({
            "timestamp": time.time(),
            "cpu_usage_percent": cpu_usage
        })
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(logs, f)
        return LOGFILE_PATH
    except IOError:
        return None

